BEGIN;

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'tradingview', 'en', 'TradingView', 'https://tradingview.com', 'tradingview.com',
  'business-investment', 'freemium', '50M+',
  'Charting, technical analysis, market screening',
  'TradingView is the world''s most popular charting and market analysis platform — with over 50 million users globally and a social network of traders that has no real competitor.',
  'TradingView is the world''s most popular charting and market analysis platform — with over 50 million users globally and a social network of traders that has no real competitor. Originally a charting tool, it has evolved into a comprehensive market intelligence hub combining professional-grade technical analysis, AI-powered screeners, real-time data across every asset class, and a community where traders share ideas, scripts, and strategies publicly.

The AI features in TradingView center on its screener and signal tools: you can set up complex multi-condition filters across thousands of stocks, ETFs, crypto, and forex pairs, and have the platform automatically scan and surface candidates that match your criteria. Smart Alerts notify you the moment a price, volume, or indicator threshold is crossed — across any instrument, on any timeframe. The platform also supports Pine Script, a proprietary scripting language that lets you write custom indicators and strategies and backtest them against historical data. An active marketplace of community-written scripts means most ideas you can think of already have a ready-made indicator.

TradingView offers a feature-rich free plan with real-time data for most markets. Paid plans start at $14.95 per month (Essential) and scale up to $59.95 per month (Ultimate) for additional chart panes, faster alerts, more indicators per chart, and extended historical data. For any investor or trader who needs professional charts, multi-market coverage, and community intelligence in one place — TradingView is the industry standard that everyone eventually ends up using.',
  ARRAY['50M+ users and the largest trader community — ideas, scripts and strategies shared publicly','Covers every asset class: stocks, ETFs, crypto, forex, futures and commodities','Pine Script lets you build and backtest custom indicators and strategies'],
  ARRAY['AI features are screener-based — no predictive signals or portfolio management tools','Real-time data for some exchanges requires paid plan'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'tradingview', 'he', 'TradingView', 'https://tradingview.com', 'tradingview.com',
  'business-investment', 'freemium', '50M+',
  'גרפים, ניתוח טכני, סקירת שוק',
  'TradingView היא פלטפורמת הגרפים וניתוח השוק הפופולרית ביותר בעולם — עם למעלה מ-50 מיליון משתמשים גלובליים ורשת חברתית של סוחרים שאין לה מתחרה אמיתי.',
  'TradingView היא פלטפורמת הגרפים וניתוח השוק הפופולרית ביותר בעולם — עם למעלה מ-50 מיליון משתמשים גלובליים ורשת חברתית של סוחרים שאין לה מתחרה אמיתי. מה שהתחיל ככלי גרפים התפתח למרכז מודיעין שוק מקיף המשלב ניתוח טכני ברמה מקצועית, סקרינרים מבוססי AI, נתונים בזמן אמת על כל סוגי הנכסים, וקהילה שבה סוחרים חולקים רעיונות, סקריפטים ואסטרטגיות בפומבי.

תכונות ה-AI ב-TradingView מתמקדות בכלי הסקרינר והסיגנל: ניתן להגדיר פילטרים מורכבים עם תנאים מרובים על פני אלפי מניות, ETF, קריפטו וזוגות פורקס, והפלטפורמה סורקת אוטומטית ומציפה מועמדים שתואמים לקריטריונים שלך. Smart Alerts מודיעים לך ברגע שמחיר, נפח, או סף אינדיקטור נחצה — על כל מכשיר, בכל מסגרת זמן. הפלטפורמה תומכת גם ב-Pine Script — שפת סקריפטינג קניינית לכתיבת אינדיקטורים ואסטרטגיות מותאמות אישית עם backtesting.

TradingView מציעה תוכנית חינמית עשירה בתכונות עם נתונים בזמן אמת לרוב השווקים. תוכניות בתשלום מתחילות מ-14.95 דולר לחודש ועולות עד 59.95 דולר לחודש. לכל משקיע או סוחר שצריך גרפים מקצועיים, כיסוי רב-שוקי ומודיעין קהילתי במקום אחד — TradingView הוא הסטנדרט שכולם בסוף מגיעים אליו.',
  ARRAY['50M+ משתמשים וקהילת הסוחרים הגדולה ביותר — רעיונות, סקריפטים ואסטרטגיות משותפים פומבית','מכסה כל סוג נכסים: מניות, ETF, קריפטו, פורקס, חוזים עתידיים וסחורות','Pine Script מאפשר בניית אינדיקטורים ואסטרטגיות מותאמות עם backtesting'],
  ARRAY['תכונות ה-AI מבוססות סקרינר — אין סיגנלים חזויים או כלי ניהול תיקים','נתונים בזמן אמת לחלק מהבורסות דורשים תוכנית בתשלום'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'tradingview', 'es', 'TradingView', 'https://tradingview.com', 'tradingview.com',
  'business-investment', 'freemium', '50M+',
  'Gráficos, análisis técnico, screening de mercado',
  'TradingView es la plataforma de gráficos y análisis de mercado más popular del mundo — con más de 50 millones de usuarios globales y una red social de traders que no tiene competidor real.',
  'TradingView es la plataforma de gráficos y análisis de mercado más popular del mundo — con más de 50 millones de usuarios globales y una red social de traders que no tiene competidor real. Originalmente una herramienta de gráficos, ha evolucionado hacia un hub integral de inteligencia de mercado que combina análisis técnico de grado profesional, screeners impulsados por IA, datos en tiempo real de todas las clases de activos, y una comunidad donde los traders comparten ideas, scripts y estrategias públicamente.

Las características de IA en TradingView se centran en sus herramientas de screener y señal: puedes configurar filtros complejos de múltiples condiciones en miles de acciones, ETFs, cripto y pares de forex, y la plataforma escanea automáticamente y muestra candidatos que coinciden con tus criterios. Smart Alerts te notifican en el momento en que se cruza un umbral de precio, volumen o indicador. La plataforma también soporta Pine Script, un lenguaje de scripting propietario para escribir indicadores y estrategias personalizadas con backtesting.

TradingView ofrece un plan gratuito rico en funciones con datos en tiempo real para la mayoría de los mercados. Los planes de pago comienzan en $14.95 por mes. Para cualquier inversor o trader que necesite gráficos profesionales, cobertura multi-mercado e inteligencia comunitaria en un solo lugar — TradingView es el estándar de la industria al que todos terminan recurriendo.',
  ARRAY['50M+ usuarios y la mayor comunidad de traders — ideas, scripts y estrategias compartidos públicamente','Cubre todas las clases de activos: acciones, ETFs, cripto, forex, futuros y materias primas','Pine Script permite construir y hacer backtesting de indicadores y estrategias personalizados'],
  ARRAY['Las funciones de IA son basadas en screener — sin señales predictivas ni herramientas de gestión de cartera','Los datos en tiempo real para algunas bolsas requieren plan de pago'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'tradingview', 'de', 'TradingView', 'https://tradingview.com', 'tradingview.com',
  'business-investment', 'freemium', '50M+',
  'Charting, technische Analyse, Markt-Screening',
  'TradingView ist die weltweit beliebteste Charting- und Marktanalyseplattform — mit über 50 Millionen Nutzern weltweit und einem sozialen Netzwerk für Trader, das keinen echten Konkurrenten hat.',
  'TradingView ist die weltweit beliebteste Charting- und Marktanalyseplattform — mit über 50 Millionen Nutzern weltweit und einem sozialen Netzwerk für Trader, das keinen echten Konkurrenten hat. Ursprünglich ein Charting-Tool, hat es sich zu einem umfassenden Marktintelligenz-Hub entwickelt, der professionelles technisches Analyse, KI-gestützte Screener, Echtzeit-Daten über alle Anlageklassen und eine Community kombiniert, in der Trader Ideen, Skripte und Strategien öffentlich teilen.

Die KI-Funktionen in TradingView konzentrieren sich auf Screener- und Signal-Tools: Man kann komplexe Mehrbedingungs-Filter über Tausende von Aktien, ETFs, Krypto und Forex-Paaren einrichten, und die Plattform scannt automatisch und zeigt Kandidaten an, die den Kriterien entsprechen. Smart Alerts benachrichtigen sofort, wenn ein Preis-, Volumen- oder Indikatorschwellenwert überschritten wird. Die Plattform unterstützt auch Pine Script — eine proprietäre Skriptsprache zum Schreiben benutzerdefinierter Indikatoren und Strategien mit Backtesting.

TradingView bietet einen funktionsreichen kostenlosen Plan mit Echtzeit-Daten für die meisten Märkte. Bezahlpläne beginnen bei $14.95 pro Monat. Für jeden Investor oder Trader, der professionelle Charts, Multi-Markt-Abdeckung und Community-Intelligenz an einem Ort braucht — TradingView ist der Industriestandard, bei dem alle letztendlich landen.',
  ARRAY['50M+ Nutzer und die größte Trader-Community — Ideen, Skripte und Strategien öffentlich geteilt','Deckt jede Anlageklasse ab: Aktien, ETFs, Krypto, Forex, Futures und Rohstoffe','Pine Script ermöglicht das Erstellen und Backtesting benutzerdefinierter Indikatoren und Strategien'],
  ARRAY['KI-Funktionen sind Screener-basiert — keine prädiktiven Signale oder Portfolio-Management-Tools','Echtzeit-Daten für einige Börsen erfordern kostenpflichtigen Plan'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'tradingview', 'ru', 'TradingView', 'https://tradingview.com', 'tradingview.com',
  'business-investment', 'freemium', '50M+',
  'Графики, технический анализ, скрининг рынка',
  'TradingView — самая популярная платформа для построения графиков и рыночного анализа в мире — с более чем 50 миллионами пользователей и социальной сетью трейдеров, у которой нет реального конкурента.',
  'TradingView — самая популярная платформа для построения графиков и рыночного анализа в мире — с более чем 50 миллионами пользователей и социальной сетью трейдеров, у которой нет реального конкурента. Начав как инструмент для графиков, платформа эволюционировала в комплексный центр рыночной аналитики, сочетающий профессиональный технический анализ, AI-скринеры, данные в реальном времени по всем классам активов и сообщество, где трейдеры публично делятся идеями, скриптами и стратегиями.

AI-функции TradingView сосредоточены в инструментах скринера и сигналов: можно настраивать сложные многоусловные фильтры по тысячам акций, ETF, крипто и форекс-пар, и платформа автоматически сканирует и выдаёт кандидатов по заданным критериям. Smart Alerts уведомляют в момент пересечения ценового, объёмного или индикаторного порога. Платформа также поддерживает Pine Script — собственный язык для написания кастомных индикаторов и стратегий с бэктестингом.

TradingView предлагает богатый бесплатный план с данными в реальном времени для большинства рынков. Платные планы начинаются от $14.95 в месяц. Для любого инвестора или трейдера, которому нужны профессиональные графики, мультирыночное покрытие и коллективный интеллект в одном месте — TradingView это отраслевой стандарт, к которому все в итоге приходят.',
  ARRAY['50M+ пользователей и крупнейшее сообщество трейдеров — идеи, скрипты и стратегии в открытом доступе','Покрывает все классы активов: акции, ETF, крипто, форекс, фьючерсы и сырьё','Pine Script позволяет создавать и бэктестировать кастомные индикаторы и стратегии'],
  ARRAY['AI-функции основаны на скринере — нет предсказательных сигналов и инструментов управления портфелем','Данные в реальном времени для части бирж требуют платного плана'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'tradingview', 'ua', 'TradingView', 'https://tradingview.com', 'tradingview.com',
  'business-investment', 'freemium', '50M+',
  'Графіки, технічний аналіз, скринінг ринку',
  'TradingView — найпопулярніша платформа для побудови графіків і ринкового аналізу у світі — з понад 50 мільйонами користувачів та соціальною мережею трейдерів, у якої немає реального конкурента.',
  'TradingView — найпопулярніша платформа для побудови графіків і ринкового аналізу у світі — з понад 50 мільйонами користувачів та соціальною мережею трейдерів, у якої немає реального конкурента. Розпочавши як інструмент для графіків, платформа еволюціонувала у комплексний центр ринкової аналітики, що поєднує професійний технічний аналіз, AI-скринери, дані в реальному часі по всіх класах активів і спільноту, де трейдери публічно діляться ідеями, скриптами та стратегіями.

AI-функції TradingView зосереджені в інструментах скринера і сигналів: можна налаштовувати складні багатоумовні фільтри по тисячах акцій, ETF, крипто та форекс-пар, і платформа автоматично сканує та видає кандидатів за заданими критеріями. Smart Alerts сповіщають у момент перетину цінового, об''ємного або індикаторного порогу. Платформа також підтримує Pine Script — власну мову для написання кастомних індикаторів і стратегій з бектестингом.

TradingView пропонує багатий безкоштовний план з даними в реальному часі для більшості ринків. Платні плани починаються від $14.95 на місяць. Для будь-якого інвестора або трейдера, якому потрібні професійні графіки, мультиринкове покриття та колективний інтелект в одному місці — TradingView це галузевий стандарт, до якого всі врешті-решт приходять.',
  ARRAY['50M+ користувачів та найбільша спільнота трейдерів — ідеї, скрипти та стратегії у відкритому доступі','Покриває всі класи активів: акції, ETF, крипто, форекс, фючерси та сировину','Pine Script дозволяє створювати та бектестувати кастомні індикатори і стратегії'],
  ARRAY['AI-функції базуються на скринері — немає предиктивних сигналів і інструментів управління портфелем','Дані в реальному часі для частини бірж потребують платного плану'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'finchat', 'en', 'FinChat', 'https://finchat.io', 'finchat.io',
  'business-investment', 'freemium', '150K+',
  'Investment research, equity analysis, financial KPIs',
  'FinChat is an AI-powered investment research platform trusted by over 150,000 investors — and the closest thing retail investors have ever had to an institutional Bloomberg terminal.',
  'FinChat is an AI-powered investment research platform trusted by over 150,000 investors — and the closest thing retail investors have ever had to an institutional Bloomberg terminal. The platform combines verified financial data on more than 100,000 global public companies with a conversational AI copilot that lets you ask complex questions and get precise, cited answers in seconds. Instead of hunting through PDFs and spreadsheets, you simply ask: "What was Amazon''s AWS revenue growth over the last 8 quarters?" — and FinChat pulls the data, builds the chart, and explains the trend.

What sets FinChat apart from general AI tools like ChatGPT is the quality and specificity of its data. It tracks over 2,000 company-specific KPIs — metrics like Netflix''s paying subscribers, Starbucks'' same-store sales, or Apple''s iPhone average selling price — that never appear in standard financial screeners. It also includes earnings call transcripts, SEC filings, analyst estimates, insider ownership, and institutional holdings, all accessible through natural language. You can build DCF models, screen stocks, and compare companies across 10,000+ metrics in a single session.

FinChat offers a free plan with access to core features including the AI Copilot and global financial data. Paid plans start at $24 per month and unlock higher data limits, priority access, and API integration for professional users and investment teams. For any investor who has ever copied data from one tab and pasted it into ChatGPT for analysis — FinChat eliminates that friction entirely and delivers the analysis faster, with real sources attached.',
  ARRAY['Institutional-grade data on 100k+ companies with cited AI answers — no hallucinations','Tracks 2,000+ company-specific KPIs unavailable in standard screeners','Free plan includes AI Copilot and global financial data'],
  ARRAY['Advanced features and API access require paid plan from $24/month','Focused on public equities only — no crypto, forex, or macro tools'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'finchat', 'he', 'FinChat', 'https://finchat.io', 'finchat.io',
  'business-investment', 'freemium', '150K+',
  'מחקר השקעות, ניתוח מניות, KPI פיננסיים',
  'FinChat היא פלטפורמת מחקר השקעות מבוססת AI שזוכה לאמון של למעלה מ-150,000 משקיעים — ונחשבת לתחליף הנגיש ביותר שקיים לטרמינל Bloomberg מוסדי עבור המשקיע הפרטי.',
  'FinChat היא פלטפורמת מחקר השקעות מבוססת AI שזוכה לאמון של למעלה מ-150,000 משקיעים — ונחשבת לתחליף הנגיש ביותר שקיים לטרמינל Bloomberg מוסדי עבור המשקיע הפרטי. הפלטפורמה משלבת נתונים פיננסיים מאומתים על יותר מ-100,000 חברות ציבוריות גלובליות עם עוזר AI שיחותי שמאפשר לשאול שאלות מורכבות ולקבל תשובות מדויקות ומצוטטות תוך שניות. במקום לחפש ב-PDF-ים וגיליונות, פשוט שואלים: "מה היה קצב הצמיחה של AWS של אמזון ב-8 הרבעונות האחרונים?" — ו-FinChat שולפת את הנתונים, בונה את הגרף ומסבירה את המגמה.

מה שמייחד את FinChat מכלי AI כלליים כמו ChatGPT הוא האיכות והספציפיות של הנתונים. הפלטפורמה עוקבת אחר למעלה מ-2,000 KPI ספציפיים לחברות — מדדים כמו מנויים משלמים של Netflix, מכירות חנויות זהות של Starbucks, או מחיר מכירה ממוצע של iPhone של Apple — שלעולם לא מופיעים בסקרינרים פיננסיים סטנדרטיים. הפלטפורמה כוללת גם תמלילי שיחות רווחים, הגשות SEC, הערכות אנליסטים, בעלות פנימית ואחזקות מוסדיות.

FinChat מציעה תוכנית חינמית עם גישה לתכונות הליבה כולל ה-AI Copilot ונתונים פיננסיים גלובליים. תוכניות בתשלום מתחילות מ-24 דולר לחודש. לכל משקיע שאי פעם העתיק נתונים מטאב אחד והדביק אותם ב-ChatGPT לניתוח — FinChat מבטלת את החיכוך הזה לחלוטין ומספקת את הניתוח מהר יותר עם מקורות אמיתיים מצורפים.',
  ARRAY['נתונים מוסדיים על 100K+ חברות עם תשובות AI מצוטטות — ללא הזיות','עוקב אחר 2,000+ KPI ספציפיים לחברות שאינם זמינים בסקרינרים רגילים','תוכנית חינמית כוללת AI Copilot ונתונים פיננסיים גלובליים'],
  ARRAY['תכונות מתקדמות וגישת API דורשות תוכנית בתשלום מ-$24 לחודש','מתמקד במניות ציבוריות בלבד — אין קריפטו, פורקס או כלים מאקרו'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'finchat', 'es', 'FinChat', 'https://finchat.io', 'finchat.io',
  'business-investment', 'freemium', '150K+',
  'Investigación de inversiones, análisis de acciones, KPIs financieros',
  'FinChat es una plataforma de investigación de inversiones impulsada por IA en la que confían más de 150,000 inversores — y lo más parecido que un inversor minorista ha tenido a un terminal Bloomberg institucional.',
  'FinChat es una plataforma de investigación de inversiones impulsada por IA en la que confían más de 150,000 inversores — y lo más parecido que un inversor minorista ha tenido a un terminal Bloomberg institucional. La plataforma combina datos financieros verificados de más de 100,000 empresas públicas globales con un copiloto de IA conversacional que permite hacer preguntas complejas y obtener respuestas precisas y citadas en segundos. En lugar de buscar en PDFs y hojas de cálculo, simplemente preguntas: "¿Cuál fue el crecimiento de los ingresos de AWS de Amazon durante los últimos 8 trimestres?" — y FinChat extrae los datos, construye el gráfico y explica la tendencia.

Lo que distingue a FinChat de las herramientas de IA generales como ChatGPT es la calidad y especificidad de sus datos. La plataforma rastrea más de 2,000 KPIs específicos de empresas — métricas como los suscriptores de pago de Netflix, las ventas en tiendas comparables de Starbucks, o el precio de venta promedio del iPhone de Apple — que nunca aparecen en los screeners financieros estándar. También incluye transcripciones de llamadas de ganancias, presentaciones SEC, estimaciones de analistas, propiedad interna y tenencias institucionales, todo accesible a través del lenguaje natural.

FinChat ofrece un plan gratuito con acceso a características principales incluyendo el Copiloto de IA y datos financieros globales. Los planes de pago comienzan en $24 por mes. Para cualquier inversor que alguna vez haya copiado datos de una pestaña y los haya pegado en ChatGPT para análisis — FinChat elimina completamente esa fricción y entrega el análisis más rápido, con fuentes reales adjuntas.',
  ARRAY['Datos de nivel institucional sobre 100K+ empresas con respuestas AI citadas — sin alucinaciones','Rastrea 2,000+ KPIs específicos de empresas no disponibles en screeners estándar','El plan gratuito incluye AI Copilot y datos financieros globales'],
  ARRAY['Las funciones avanzadas y el acceso API requieren plan de pago desde $24/mes','Enfocado solo en renta variable pública — sin cripto, forex ni herramientas macro'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'finchat', 'de', 'FinChat', 'https://finchat.io', 'finchat.io',
  'business-investment', 'freemium', '150K+',
  'Investmentrecherche, Aktienanalyse, Finanz-KPIs',
  'FinChat ist eine KI-gestützte Investment-Research-Plattform, der über 150.000 Investoren vertrauen — und das Nächste, was Privatanleger je einem institutionellen Bloomberg-Terminal hatten.',
  'FinChat ist eine KI-gestützte Investment-Research-Plattform, der über 150.000 Investoren vertrauen — und das Nächste, was Privatanleger je einem institutionellen Bloomberg-Terminal hatten. Die Plattform kombiniert verifizierte Finanzdaten zu mehr als 100.000 globalen börsennotierten Unternehmen mit einem konversationellen KI-Copiloten, mit dem man komplexe Fragen stellen und in Sekunden präzise, zitierte Antworten erhalten kann. Statt PDFs und Tabellen zu durchsuchen, fragt man einfach: "Wie war das Umsatzwachstum von Amazons AWS in den letzten 8 Quartalen?" — und FinChat ruft die Daten ab, erstellt das Diagramm und erklärt den Trend.

Was FinChat von allgemeinen KI-Tools wie ChatGPT unterscheidet, ist die Qualität und Spezifität seiner Daten. Die Plattform verfolgt über 2.000 unternehmensspezifische KPIs — Kennzahlen wie Netflixs zahlende Abonnenten, Starbucks'' Same-Store-Sales oder Apples durchschnittlichen iPhone-Verkaufspreis — die in Standard-Finanzscreenern nie erscheinen. Sie umfasst auch Earnings-Call-Transkripte, SEC-Einreichungen, Analystenprognosen, Insider-Eigentümerschaft und institutionelle Bestände.

FinChat bietet einen kostenlosen Plan mit Zugang zu Kernfunktionen einschließlich des KI-Copiloten und globaler Finanzdaten. Bezahlpläne beginnen bei $24 pro Monat. Für jeden Investor, der schon einmal Daten aus einem Tab kopiert und in ChatGPT zur Analyse eingefügt hat — FinChat eliminiert diese Reibung vollständig und liefert die Analyse schneller, mit echten Quellen.',
  ARRAY['Institutionelle Daten zu 100K+ Unternehmen mit zitierten KI-Antworten — keine Halluzinationen','Verfolgt 2.000+ unternehmensspezifische KPIs, die in Standard-Screenern nicht verfügbar sind','Kostenloser Plan umfasst KI-Copilot und globale Finanzdaten'],
  ARRAY['Erweiterte Funktionen und API-Zugang erfordern kostenpflichtigen Plan ab $24/Monat','Fokussiert ausschließlich auf börsennotierte Aktien — kein Krypto, Forex oder Makro-Tools'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
  'finchat', 'ru', 'FinChat', 'https://finchat.io', 'finchat.io',
  'business-investment', 'freemium', '150K+',
  'Исследование инвестиций, анализ акций, финансовые KPI',
  'FinChat — это AI-платформа для инвестиционных исследований, которой доверяют более 150,000 инвесторов — и ближайший аналог институционального терминала Bloomberg, доступный рядовому инвестору.',
  'FinChat — это AI-платформа для инвестиционных исследований, которой доверяют более 150,000 инвесторов — и ближайший аналог институционального терминала Bloomberg, доступный рядовому инвестору. Платформа объединяет верифицированные финансовые данные по более чем 100,000 публичных компаний по всему миру с разговорным AI-помощником, который позволяет задавать сложные вопросы и получать точные, подкреплённые источниками ответы за секунды. Вместо того чтобы рыскать по PDF-файлам и таблицам, просто спрашиваешь: "Какой был рост выручки AWS Amazon за последние 8 кварталов?" — и FinChat достаёт данные, строит график и объясняет тренд.

Что отличает FinChat от общих AI-инструментов вроде ChatGPT — качество и специфичность данных. Платформа отслеживает более 2,000 компания-специфичных KPI — метрики вроде платных подписчиков Netflix, продаж в сопоставимых магазинах Starbucks или среднего ценника iPhone у Apple — которые никогда не появляются в стандартных финансовых скринерах. Также включены транскрипты earnings calls, документы SEC, прогнозы аналитиков, инсайдерское владение и институциональные позиции.

FinChat предлагает бесплатный план с доступом к ключевым функциям, включая AI Copilot и глобальные финансовые данные. Платные планы начинаются от $24 в месяц. Для любого инвестора, который когда-либо копировал данные из одной вкладки и вставлял в ChatGPT для анализа — FinChat полностью убирает этот барьер и выдаёт анализ быстрее, с реальными источниками.',
  ARRAY['Институциональные данные по 100K+ компаниям с цитированными ответами AI — без галлюцинаций','Отслеживает 2,000+ компания-специфичных KPI, недоступных в стандартных скринерах','Бесплатный план включает AI Copilot и глобальные финансовые данные'],
  ARRAY['Расширенные функции и доступ к API требуют платного плана от $24/месяц','Фокус только на публичных акциях — нет крипто, форекса и макро-инструментов'],
  true);

INSERT INTO tools (slug, lang, name, url, domain, category, badge, users, best_for, description, description_long, pros, cons, published) VALUES (
